@startuml

class Museum {
  + name : string
}

abstract class Location {}

class ExhibitionRoom {
  + locationId : int
  + exhibitionStatus : string
  + coordinator : Employee
}

class ExhibitionItem {
  + itemId : int
  + description : string
  + requiredPieces : int
  + availablePieces : int
}

class Collector {
  + collectorId : int
  + pieceCount : int
}

class PieceRequest {
  + requestId : int
  + itemId : int
  + collectorId : int
  + status : string
}

class Employee {
  + employeeId : int
  + name : string
  + coach : Employee
}

Location *-- ExhibitionRoom
ExhibitionRoom "1" -- "0..*" ExhibitionItem
ExhibitionItem "0..*" -- "0..*" PieceRequest
PieceRequest "1" -- "1" Collector
Employee "0..1" -- "1" Employee : Coach

@enduml

